css:
.wrap { max-width: 1360px; margin: 0 auto; }
#faq { padding: 90px 40px; border-top: 1px solid var(--border); border-bottom: 1px solid var(--border); }

.faq-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 64px; align-items: start; }
.faq-heading {
  font-family: 'Sora', sans-serif; font-weight: 700; font-size: clamp(32px, 4vw, 48px); letter-spacing: -0.03em; line-height: 1.05;
}
.faq-heading .dim { color: #555; }

.faq-list { display: flex; flex-direction: column; border-top: 1px solid var(--border); }
.faq-item { border-bottom: 1px solid var(--border); padding: 24px 0; cursor: pointer; }
.faq-row { display: flex; justify-content: space-between; align-items: center; gap: 24px; }
.faq-q { font-weight: 600; font-size: 18px; letter-spacing: -0.01em; color: #d4d4d4; }
.faq-q.open { color: #fff; }
.faq-sign { font-size: 20px; color: var(--accent); flex-shrink: 0; line-height: 1; }
.faq-a {
  font-family: 'Manrope', sans-serif; font-size: 15px; color: var(--text-muted); line-height: 1.6; max-width: 620px;
  overflow: hidden; max-height: 0; opacity: 0; margin-top: 0; transition: all 0.35s ease;
}
.faq-a.open { max-height: 200px; opacity: 1; margin-top: 14px; }

js:
export function initFaq(faqs) {
  const faqList = document.getElementById('faqList');
  let openIndex = 0;

  function render() {
    faqList.innerHTML = '';
    faqs.forEach(function (item, i) {
      const isOpen = i === openIndex;
      const row = document.createElement('div');
      row.className = 'faq-item';
      row.innerHTML =
        '<div class="faq-row">' +
          '<span class="faq-q sora' + (isOpen ? ' open' : '') + '">' + item.q + '</span>' +
          '<span class="faq-sign mono">' + (isOpen ? '−' : '+') + '</span>' +
        '</div>' +
        '<div class="faq-a' + (isOpen ? ' open' : '') + '">' + item.a + '</div>';
      row.addEventListener('click', function () {
        openIndex = isOpen ? -1 : i;
        render();
      });
      faqList.appendChild(row);
    });
  }

  render();
}

